<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->prepare('SELECT sf.*,fs.name fee_structure FROM student_fees sf LEFT JOIN fee_structures fs ON fs.id=sf.fee_structure_id JOIN students s ON s.id=sf.student_id WHERE s.user_id=? ORDER BY sf.due_date');$q->execute([actor_id()]);page_top('Digital Fees');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Fee</th><th>Amount</th><th>Discount</th><th>Paid</th><th>Balance</th><th>Due</th><th>Status</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['category'])?></td><td>₹<?=e(number_format($r['amount'],2))?></td><td>₹<?=e(number_format($r['discount'],2))?></td><td>₹<?=e(number_format($r['paid_amount'],2))?></td><td>₹<?=e(number_format(max(0,$r['amount']-$r['discount']-$r['paid_amount']),2))?></td><td><?=e($r['due_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><a class='btn btn-primary mt-3' href='payments.php'>Make Demo Payment / View Receipts</a><?php page_bottom(); ?>